async function authCall(path, body, token) {
  const headers = { apikey: CLOUD_KEY, "Content-Type": "application/json" };
  if (token) headers.Authorization = "Bearer " + token;
  const response = await request(CLOUD_URL + path, {
    method: "POST",
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await response.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch (error) {
    data = { message: text };
  }
  if (!response.ok) throw cloudError(response.status, data);
  return data;
}

async function refreshAuth() {
  if (!authSession || !authSession.refresh_token) return null;
  if (!refreshPromise) {
    refreshPromise = (async () => {
      const epoch = authEpoch;
      try {
        const data = await authCall("/auth/v1/token?grant_type=refresh_token", { refresh_token: authSession.refresh_token });
        const next = normalizeAuth(data);
        // 退出登录期间完成的刷新结果不能再写回，否则会重新恢复已退出的会话。
        if (next && epoch === authEpoch) setAuth(next);
        return epoch === authEpoch ? next : null;
      } catch (error) {
        clearAuth();
        return null;
      } finally {
        refreshPromise = null;
      }
    })();
  }
  return refreshPromise;
}

async function ensureFreshAuth() {
  if (!authSession) authSession = readAuth();
  if (!authSession) return null;
  if (authSession.expires_at - 60000 < Date.now() && authSession.refresh_token) {
    await refreshAuth();
  }
  return authSession;
}

async function api(path, options = {}, retried = false) {
  await ensureFreshAuth();
  const headers = { apikey: CLOUD_KEY, Accept: "application/json" };
  if (authSession && authSession.access_token) headers.Authorization = "Bearer " + authSession.access_token;
  if (options.body !== undefined) headers["Content-Type"] = "application/json";
  if (options.prefer) headers.Prefer = options.prefer;
  if (options.headers) Object.assign(headers, options.headers);
  const response = await request(CLOUD_URL + path, {
    method: options.method || "GET",
    headers,
    body: options.body === undefined ? undefined : JSON.stringify(options.body),
  });
  if (response.status === 401 && !retried && authSession && authSession.refresh_token) {
    const next = await refreshAuth();
    if (next) return api(path, options, true);
  }
  const text = await response.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch (error) {
    data = text;
  }
  if (!response.ok) throw cloudError(response.status, data);
  return data;
}

async function apiCount(path, retried = false) {
  await ensureFreshAuth();
  const headers = { apikey: CLOUD_KEY, Accept: "application/json", Prefer: "count=exact", Range: "0-0" };
  if (authSession && authSession.access_token) headers.Authorization = "Bearer " + authSession.access_token;
  const response = await request(CLOUD_URL + path, { headers });
  if (response.status === 401 && !retried && authSession && authSession.refresh_token) {
    const next = await refreshAuth();
    if (next) return apiCount(path, true);
  }
  if (!response.ok) {
    const text = await response.text();
    let data = null;
    try {
      data = JSON.parse(text);
    } catch (error) {
      data = { message: text };
    }
    throw cloudError(response.status, data);
  }
  const range = response.headers.get("content-range") || "";
  const total = Number(range.split("/")[1]);
  return Number.isFinite(total) ? total : 0;
}

async function restoreAuth() {
  authSession = readAuth();
  if (!authSession || !authSession.access_token) return null;
  if (!authSession.user || !authSession.user.id) {
    try {
      const user = await api("/auth/v1/user");
      if (user && user.id) {
        authSession = { ...authSession, user };
        writeJson(AUTH_KEY, authSession);
      }
    } catch (error) {
      if (error.status === 401) {
        const next = await refreshAuth();
        if (!next) return null;
      }
    }
  }
  const fresh = await ensureFreshAuth();
  return fresh && fresh.access_token ? fresh : null;
}

async function signUp(email, password, nickname) {
  const data = await authCall("/auth/v1/signup", {
    email,
    password,
    data: { nickname },
  });
  const session = normalizeAuth(data && data.session);
  if (session) setAuth(session);
  return { session, user: (data && data.user) || null, needsConfirm: !session };
}

async function signIn(email, password) {
  const data = await authCall("/auth/v1/token?grant_type=password", { email, password });
  const session = normalizeAuth(data);
  if (!session) throw new CloudError("invalid_session", 0, "invalid_session");
  setAuth(session);
  return session;
}

// 修改密码前先用当前密码重新登录验证，再调用 Supabase 的更新用户接口。
async function changePassword(currentPassword, nextPassword) {
  const auth = await restoreAuth();
  const email = auth?.user?.email || "";
  if (!email) throw new CloudError("not_authenticated", 401, "not_authenticated");
  const verified = await authCall("/auth/v1/token?grant_type=password", { email, password: currentPassword });
  const fresh = normalizeAuth(verified);
  if (!fresh) throw new CloudError("invalid_credentials", 400, "invalid_credentials");
  const response = await request(CLOUD_URL + "/auth/v1/user", {
    method: "PUT",
    headers: {
      apikey: CLOUD_KEY,
      Authorization: "Bearer " + fresh.access_token,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ password: nextPassword }),
  });
  const text = await response.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch (error) {
    data = { message: text };
  }
  if (!response.ok) throw cloudError(response.status, data);
  setAuth(fresh);
  return true;
}

